const menuButton=document.querySelector('.menu-button');const menu=document.querySelector('nav');if(menuButton){menuButton.addEventListener('click',()=>{const open=menu.classList.toggle('open');menuButton.setAttribute('aria-expanded',open);menuButton.textContent=open?'Cerrar':'Menú';});}

// Monograma consistente en todas las páginas del portafolio.
document.querySelectorAll('.brand').forEach(brand=>{if(brand.firstChild)brand.firstChild.nodeValue='JD';});

// Adaptación sin dependencias del efecto "Magnetic Button" de 21st.dev (licencia MIT).
document.querySelectorAll('.round-link').forEach(link=>{link.addEventListener('pointermove',event=>{const box=link.getBoundingClientRect();const x=(event.clientX-box.left-box.width/2)*.18;const y=(event.clientY-box.top-box.height/2)*.18;link.style.transform=`translate(${x}px, ${y}px) rotate(8deg)`;});link.addEventListener('pointerleave',()=>{link.style.transform='';});});

// Parallax editorial: el contenido responde al cursor sin añadir formas encima de la página.
if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){const hero=document.querySelector('.hero');if(hero){const title=hero.querySelector('h1');const orbit=hero.querySelector('.orbit');hero.addEventListener('pointermove',event=>{const box=hero.getBoundingClientRect();const x=(event.clientX-box.left)/box.width-.5;const y=(event.clientY-box.top)/box.height-.5;title.style.transform=`translate3d(${x*18}px,${y*12}px,0)`;if(orbit)orbit.style.transform=`translate3d(${x*-28}px,${y*-18}px,0) rotate(${x*12}deg)`;});hero.addEventListener('pointerleave',()=>{title.style.transform='';if(orbit)orbit.style.transform='';});}document.querySelectorAll('.project-item').forEach(card=>{card.addEventListener('pointermove',event=>{const box=card.getBoundingClientRect();const x=(event.clientX-box.left)/box.width-.5;const y=(event.clientY-box.top)/box.height-.5;card.style.transform=`translate3d(${x*8}px,${y*8}px,0)`;});card.addEventListener('pointerleave',()=>{card.style.transform='';});});}

// Galerías de proyectos editoriales: miniaturas, flechas y teclado.
document.querySelectorAll('[data-gallery]').forEach(gallery=>{const thumbs=[...gallery.querySelectorAll('[data-gallery-thumb]')];const stage=gallery.querySelector('[data-gallery-stage]');const caption=gallery.querySelector('[data-gallery-caption]');const counter=gallery.querySelector('[data-gallery-counter]');let current=0;const render=index=>{current=(index+thumbs.length)%thumbs.length;const thumb=thumbs[current];stage.src=thumb.dataset.src;stage.alt=thumb.dataset.alt||'';caption.textContent=thumb.dataset.caption||'';counter.textContent=`${String(current+1).padStart(2,'0')} / ${String(thumbs.length).padStart(2,'0')}`;thumbs.forEach((item,i)=>item.classList.toggle('is-active',i===current));};thumbs.forEach((thumb,index)=>thumb.addEventListener('click',()=>render(index)));gallery.querySelector('[data-gallery-prev]')?.addEventListener('click',()=>render(current-1));gallery.querySelector('[data-gallery-next]')?.addEventListener('click',()=>render(current+1));gallery.addEventListener('keydown',event=>{if(event.key==='ArrowLeft')render(current-1);if(event.key==='ArrowRight')render(current+1);});gallery.tabIndex=0;});
